package org.zhixiaoce.aperture;
import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.json.*;
public final class ReleaseReadinessTest {
 static int count;interface Run{void run()throws Exception;}static void check(boolean b,String name){if(!b)throw new AssertionError(name);count++;}static void reject(Run r,String name)throws Exception{try{r.run();}catch(Exception expected){count++;return;}throw new AssertionError(name);}
 static CinemaCatalog.Line line(String...names){CinemaCatalog.Line out=new CinemaCatalog.Line("line");for(String n:names)out.episodes.add(new CinemaCatalog.Episode(n,"https://example.invalid/v.mp4"));return out;}
 static JSONObject item(String id,String section)throws Exception{return new JSONObject().put("id",id).put("title",id).put("section",section).put("poster","https://example.invalid/p.webp").put("summary","真实简介").put("rating",8.6).put("year",2026).put("genre","剧情").put("episodes",new JSONArray().put(new JSONObject().put("title","正片").put("url","https://example.invalid/v.mp4")));}
 static JSONObject pack()throws Exception{return new JSONObject().put("format","kaishi.resource-pack").put("version",1).put("id","mixed.test").put("revision",1).put("title","混合片单").put("resources",new JSONArray().put(new JSONObject().put("id","local").put("title","本地片单").put("type","collection").put("sections",new JSONArray().put("movies").put("series").put("variety")).put("items",new JSONArray().put(item("film","movies")).put(item("show","series")).put(item("variety","variety")))));}
 public static void main(String[] args)throws Exception{
  CinemaPlaybackPlan p=new CinemaPlaybackPlan(Arrays.asList(line("第01集","第02集"),line("第1集"),line("第5集"),line("第01集","第02集")),0,0,4000);check(p.next()&&p.line==1&&p.episode==0,"first partial line matches original episode");check(p.next()&&p.line==3&&p.episode==0,"singleton intermediate never widens to episode five");check(!p.next(),"each line only once");check(!new CinemaPlaybackPlan(Arrays.asList(line("第1集"),line("第5集")),0,0,0).next(),"single episode is not a single film");check(new CinemaPlaybackPlan(Arrays.asList(line("正片"),line("HD")),0,0,0).next(),"explicit film labels remain compatible");
  p=new CinemaPlaybackPlan(Arrays.asList(line("第01集","第02集"),line("第2集","第1集"),line("第1集","第01集")),0,0,8000);check(p.choose(1)&&p.episode==1&&p.resume==8000,"manual line matches reordered original episode");check(!p.choose(2),"ambiguous original episode rejected");
  JSONObject input=pack();CinemaCatalog.Config c=CinemaCatalog.config(input.toString(),null,false);CinemaCatalog.Site site=c.sites.get(0);check(site.supports("movies")&&site.supports("series")&&site.supports("variety"),"one collection declares three sections");CinemaHttp http=new CinemaHttp();
  for(String section:Arrays.asList("movies","series","variety")){CinemaCatalog.Page page=http.catalogue(site,section,1,null,null,false);check(page.items.size()==1,"section filters before paging: "+section);check(page.categories.size()==3,"section list persisted");}
  CinemaCatalog.Item film=http.catalogue(site,"movies",1,null,null,false).items.get(0);check(film.poster.endsWith(".webp")&&film.summary.equals("真实简介")&&film.rating.equals("8.6")&&film.year.equals("2026"),"flat aliases and numeric score/year mapped");
  CinemaCatalog.Config restored=CinemaCatalog.config(c.json(),null,false);check(http.catalogue(restored.sites.get(0),"series",1,null,null,false).items.get(0).id.equals("show"),"mixed classification survives persistence");
  JSONObject missing=pack();missing.getJSONArray("resources").getJSONObject(0).getJSONArray("items").getJSONObject(0).remove("section");reject(()->CinemaCatalog.config(missing.toString(),null,false),"mixed item must declare section");
  JSONObject array=pack();JSONObject resource=array.getJSONArray("resources").getJSONObject(0);resource.put("section",resource.remove("sections"));check(CinemaCatalog.config(array.toString(),null,false).sites.size()==1,"section array compatibility");
  JSONObject legacy=pack();resource=legacy.getJSONArray("resources").getJSONObject(0);resource.remove("sections");resource.put("section","movies");resource.put("items",new JSONArray().put(item("legacy","movies")));resource.getJSONArray("items").getJSONObject(0).remove("section");check(http.catalogue(CinemaCatalog.config(legacy.toString(),null,false).sites.get(0),"movies",1,null,null,false).items.size()==1,"legacy single section unchanged");
  for(Object score:Arrays.asList(-1,11)){JSONObject bad=pack();bad.getJSONArray("resources").getJSONObject(0).getJSONArray("items").getJSONObject(0).put("rating",score);reject(()->CinemaCatalog.config(bad.toString(),null,false),"invalid rating rejected");}
  JSONObject conflict=pack();conflict.getJSONArray("resources").getJSONObject(0).getJSONArray("items").getJSONObject(0).put("cover","https://example.invalid/other.jpg");reject(()->CinemaCatalog.config(conflict.toString(),null,false),"metadata alias conflict rejected");
  CinemaCatalog.Site remote=new CinemaCatalog.Site("remote","https://example.invalid/api","r",1,Collections.emptyMap());List<CinemaCatalog.Site> sources=Arrays.asList(remote,site);check(CinemaBrowse.preferred(sources,null,"series")==site,"local source precedes remote by default");check(CinemaBrowse.preferred(sources,remote,"series")==remote,"explicit user source retained");
  AtomicLong now=new AtomicLong(1000);LocalControlSession session=new LocalControlSession(now::get);check(!session.authorized(""),"closed by default");String pin=session.begin();check(pin.matches("[0-9]{6}"),"six digit physical pairing");String ticket=session.request(pin);check(session.claim(ticket).isEmpty(),"no token before TV confirmation");session.approve(ticket,true);String token=session.claim(ticket);check(token.length()>=40&&session.authorized(token),"token after explicit TV approval");check(!session.authorized("wrong"),"wrong token rejected");now.addAndGet(1800001);check(!session.authorized(token),"30 minute expiry enforced");pin=session.begin();ticket=session.request(pin);session.approve(ticket,false);final String denied=ticket;reject(()->session.claim(denied),"denial invalidates ticket");session.close();check(!session.authorized(token),"revocation immediate");
  pin=session.begin();for(int i=0;i<5;i++)try{session.request("not-pin");}catch(SecurityException expected){}final String blocked=pin;reject(()->session.request(blocked),"pair guessing bounded");pin=session.begin();now.addAndGet(120001);final String expired=pin;reject(()->session.request(expired),"pair window expires");
  System.out.println(count+" S79 production contract/playback/pairing assertions passed");
 }
}
